window.MOTIF_CATALOG_CHUNKS[57]={"cards":[{"id":"MEJE-KW-003485","row_version":2,"title":"피를 흘리면서 웃는 인물","original":"Bloody Smile","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"상처가 보이는데도 인물이 웃어 상대의 예상 반응을 깨뜨린다. 허세와 즐거움, 희생의 결심 중 어떤 감정인지 장면에서 드러난다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003485/index.html"},{"id":"MEJE-KW-003486","row_version":1,"title":"제작 중 생긴 실수 장면","original":"Blooper","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"촬영이나 공연 과정에서 대사와 동선, 소품이 어긋난 순간이 남는다. 편집으로 지우거나 별도의 기록으로 공개할 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003486/index.html"},{"id":"MEJE-KW-003487","row_version":1,"title":"입김으로 작은 발사체를 보내는 관","original":"Blow Gun","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"속이 빈 긴 관을 무기로 사용하는 인물이 등장한다. 작품에서는 조용한 원거리 공격의 이미지로 쓰이지만 실제 사용법의 설명은 중심이 아니다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003487/index.html"},{"id":"MEJE-KW-003488","row_version":1,"title":"혀로 내는 놀리는 소리","original":"Blowing a Raspberry","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 입으로 짧은 소리를 내 상대를 가볍게 놀린다. 말보다 유치하고 직접적인 거절이나 장난의 몸짓이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003488/index.html"},{"id":"MEJE-KW-003489","row_version":1,"title":"연기를 둥글게 내뿜기","original":"Blowing Smoke Rings","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"담배 연기를 고리 모양으로 내보내는 모습이 여유나 허세의 장면에 쓰인다. 흡연 자체의 긍정적 의미보다 인물이 만들려는 인상을 본다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003489/index.html"},{"id":"MEJE-KW-003490","row_version":1,"title":"한 번의 충격에 방 건너편까지 날아가기","original":"Blown Across the Room","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"타격을 받은 인물이 크게 밀려나 공간 끝까지 날아간다. 충격의 세기를 현실보다 과장해 보여 주는 액션 표현이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003490/index.html"},{"id":"MEJE-KW-003491","row_version":1,"title":"고래의 숨구멍에 실려 하늘로 솟기","original":"Blown Upward by a Blowhole","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 고래가 숨을 내쉴 때 위로 튀어 오르는 장면을 만든다. 실제 동물의 숨쉬기보다 만화적 우연과 이동의 재미를 앞세운다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003491/index.html"},{"id":"MEJE-KW-003492","row_version":1,"title":"쌓인 감정이 터지는 관계의 큰 싸움","original":"Blowout Fight","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"가까운 사람들이 오래 숨긴 불만을 한꺼번에 꺼내며 크게 다툰다. 한 번의 말다툼보다 그 뒤 관계가 어떻게 바뀌는지가 중요하다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003492/index.html"},{"id":"MEJE-KW-003493","row_version":1,"title":"나팔 소리가 사건을 부르기","original":"Blow That Horn","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"특별한 나팔이 군대나 존재를 모으거나 봉인된 힘을 깨우는 신호가 된다. 소리를 낸 주체와 응답해야 하는 대상이 세계의 규칙을 이룬다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003493/index.html"},{"id":"MEJE-KW-003494","row_version":1,"title":"바람을 움직이는 능력","original":"Blow You Away","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 공기의 흐름을 바꿔 이동과 방어, 공격에 사용한다. 바람의 범위와 힘의 한계가 장면의 가능성을 정한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003494/index.html"},{"id":"MEJE-KW-003495","row_version":1,"title":"둔기로 인물을 죽이는 장면","original":"Bludgeoned to Death","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"이야기에서 둔한 물건의 타격으로 사망이 발생한다. 충격의 자세한 방식보다 폭력이 남긴 피해와 사건의 책임을 다룬다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003495/index.html"},{"id":"MEJE-KW-003496","row_version":1,"title":"서로 다른 윤리 기준을 가진 존재들","original":"Blue-and-Orange Morality","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"한쪽의 선악 기준으로는 다른 존재의 선택을 쉽게 분류할 수 없다. 낯선 규범이 단순한 악행인지 일관된 가치 체계인지 살핀다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-003496/index.html"},{"id":"MEJE-KW-003497","row_version":2,"title":"행복을 알리는 파랑새","original":"Bluebird of Happiness","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"푸른 새의 등장이나 흔적을 희망과 기쁜 변화의 신호로 읽는다. 실제 새보다 사람들이 그 색과 이미지에 부여한 소망이 장면을 이끈다. 푸른색에 평온을 부여하는 파란색으로 평온을 나타내기의 인상이 새의 희망 이미지와 겹친다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003497/index.html"},{"id":"MEJE-KW-003498","row_version":1,"title":"대대로 이어지는 귀족 신분","original":"Blue Blood","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"가문의 이름과 지위를 물려받는 사람들이 정치와 사회에서 별도의 권한을 가진다. 법적 권리와 실제 영향력이 같지 않을 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003498/index.html"},{"id":"MEJE-KW-003499","row_version":1,"title":"거리의 삶을 아는 노동자형 마법사","original":"Blue-Collar Warlock","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"마법사가 귀족이나 학자보다 일하는 사람들의 생활과 말에 익숙하다. 초월적 능력과 일상의 생계가 한 인물 안에 공존한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003499/index.html"},{"id":"MEJE-KW-003500","row_version":2,"title":"블루그래스 음악","original":"Bluegrass","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"현악기의 빠른 주고받기와 합주를 중심으로 하는 음악 장르. 연주자들이 서로의 소리를 듣고 순서를 넘기는 방식이 활기를 만든다. 연주의 바탕에 블루스 음악의 선율과 표현이 스며들 수 있다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-003500/index.html"},{"id":"MEJE-KW-003501","row_version":2,"title":"파란색으로 평온을 나타내기","original":"Blue Is Calm","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"화면과 의상에 푸른빛을 써 차분한 분위기를 만든다. 색의 의미는 다른 조명과 소리, 인물의 경험에 따라 달라질 수 있다. 차분한 인상을 인물의 역할에 옮기면 파란색을 영웅의 표지로 쓰기의 색채 기호가 된다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003501/index.html"},{"id":"MEJE-KW-003502","row_version":2,"title":"파란색을 영웅의 표지로 쓰기","original":"Blue Is Heroic","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"영웅이나 그 진영에 푸른색을 반복해 신뢰와 선의의 인상을 준다. 옷의 색만으로 인물의 행동이 정당화되지는 않는다. 영웅의 선의에 더해 지혜를 강조할 때 파란색을 똑똑한 인물의 표지로 쓰기의 색채 관습과 겹친다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003502/index.html"},{"id":"MEJE-KW-003503","row_version":1,"title":"흡수력 광고에 푸른 액체 쓰기","original":"Blue Liquid Absorbent","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"위생용품의 기능을 보이는 광고가 몸의 실제 분비물 대신 파란 액체를 붓는다. 무엇을 드러내고 무엇을 가리는지가 상품의 이미지를 만든다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003503/index.html"},{"id":"MEJE-KW-003504","row_version":2,"title":"파란색으로 추위를 나타내기","original":"Blue Means Cold","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"푸른 피부나 조명을 사용해 차가운 온도를 즉시 알린다. 실제 물체의 색보다 관객이 익숙하게 읽는 시각 약속이다. 놀라 얼굴이 파랗게 변하는 표현에서도 얼굴이 파래지지만 추위보다 놀람을 나타내는 그림의 약속이다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003504/index.html"},{"id":"MEJE-KW-003505","row_version":1,"title":"파란색을 똑똑한 인물의 표지로 쓰기","original":"Blue Means Smart One","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"지식과 판단력을 강조할 인물에게 푸른색을 반복해서 부여한다. 색은 빠른 인상을 만들지만 지능의 실제 근거는 행동에 있다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003505/index.html"},{"id":"MEJE-KW-003506","row_version":2,"title":"블루스 음악","original":"Blues","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"반복되는 리듬과 선율, 목소리의 표현으로 감정을 전하는 음악 장르. 한 인물의 슬픔을 표현하는 도구에 그치지 않고 음악 자체의 형식으로 다룬다. 블루스 록 음악은 블루스의 표현을 록의 소리와 결합한 다른 장르다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-003506/index.html"},{"id":"MEJE-KW-003507","row_version":2,"title":"블루스 록 음악","original":"Blues Rock","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"블루스의 선율과 즉흥적인 연주를 록의 증폭된 소리와 결합한 음악 장르. 두 흐름의 영향을 한 곡 안에서 들을 수 있다. 결합된 소리 가운데 블루스 음악에서 온 선율과 리듬을 들을 수 있다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-003507/index.html"},{"id":"MEJE-KW-003508","row_version":1,"title":"놀라 얼굴이 파랗게 변하는 표현","original":"Blue with Shock","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 충격이나 당황을 겪을 때 얼굴에 푸른 그림자를 얹는다. 실제 몸의 변화보다 감정을 빠르게 알리는 그림의 약속이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003508/index.html"},{"id":"MEJE-KW-003509","row_version":1,"title":"먼저 온 정찰대를 속여 침공 막기","original":"Bluffing the Advance Scout","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"큰 적군보다 앞서 온 정찰대에 자신들의 힘이나 가치를 다르게 보이게 한다. 적이 불완전한 보고를 믿는지가 작전의 성패를 가른다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003509/index.html"},{"id":"MEJE-KW-003510","row_version":2,"title":"수사 기관 앞에서 무고한 척하기","original":"Bluffing the Authorities","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"의심받는 인물이 발견된 단서에 다른 설명을 붙여 조사를 피하려 한다. 거짓말이 통하는 이유는 권한과 시간, 증거의 상태에 달려 있다. 거짓 설명으로 조사를 피하려는 인물은 범인을 속여 스스로 단서를 드러내게 하기의 유도에 걸릴 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003510/index.html"},{"id":"MEJE-KW-003511","row_version":2,"title":"범인을 속여 스스로 단서를 드러내게 하기","original":"Bluffing the Murderer","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"수사자가 확실한 증거가 부족할 때 범인이 먼저 움직이도록 거짓 정보를 흘린다. 상대의 반응이 새로운 단서가 되는 추리 장치다. 수사 기관 앞에서 무고한 척하기가 단서를 감추려 새 행동을 할 때 수사자는 그 반응을 살핀다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003511/index.html"},{"id":"MEJE-KW-003512","row_version":2,"title":"도청자를 속이는 가짜 대화","original":"Bluff the Eavesdropper","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"도청 사실을 알아챈 인물들이 들으라는 듯 거짓 대화를 나눈다. 진짜 뜻은 표정이나 쪽지 등 다른 경로로 주고받는다. 도청자에게 심은 말이 지나치게 믿어지면 너무 잘 먹힌 허풍의 문제가 생긴다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003512/index.html"},{"id":"MEJE-KW-003513","row_version":1,"title":"가짜 인물에게 아는 척 질문하기","original":"Bluff the Impostor","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"누군가 다른 사람을 흉내 낸다고 의심해 실제 당사자만 알아야 할 일을 일부러 틀리게 묻는다. 상대가 거짓 전제에 동의하면 위장이 드러난다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003513/index.html"},{"id":"MEJE-KW-003514","row_version":2,"title":"너무 잘 먹힌 허풍","original":"Bluff Worked Too Well","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"상대를 잠시 속이려던 말이 지나치게 믿어져 예상보다 큰 결과를 부른다. 성공한 속임수의 뒷수습이 새 갈등이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003514/index.html"},{"id":"MEJE-KW-003515","row_version":1,"title":"남의 서투른 일을 대신 떠맡기","original":"Blunder-Correcting Impulse","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"한 인물이 일을 계속 서툴게 하자 지켜보던 사람이 답답함을 이기지 못하고 직접 맡는다. 인내심과 주도권의 변화가 짧은 행동으로 보인다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003515/index.html"},{"id":"MEJE-KW-003516","row_version":1,"title":"관용구를 엉뚱하게 섞어 말하기","original":"Blunt Metaphors Trauma","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"익숙한 비유나 속담의 낱말을 섞거나 뜻을 잘못 이해한 채 말한다. 말한 사람의 자신감과 듣는 사람의 당혹감이 웃음을 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003516/index.html"},{"id":"MEJE-KW-003517","row_version":2,"title":"짧고 단호한 거절","original":"Blunt \"No\"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"긴 설득이나 부탁을 들은 사람이 이유를 덧붙이지 않고 거절한다. 말의 짧음이 관계의 거리나 결심을 드러낸다. 즉답으로 흐름을 바꾼다는 점은 예상을 깨는 단호한 승낙와 같지만 대답의 방향은 반대다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003517/index.html"},{"id":"MEJE-KW-003518","row_version":2,"title":"예상을 깨는 단호한 승낙","original":"Blunt \"Yes\"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"질문한 사람이 완곡한 답을 기대했는데 상대가 곧바로 긍정한다. 숨길 줄 알았던 마음이 드러나며 대화의 방향이 바뀐다. 상대의 예상을 깨는 짧은 대답이라는 점에서 짧고 단호한 거절과 짝을 이룬다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003518/index.html"},{"id":"MEJE-KW-003519","row_version":1,"title":"스티커처럼 붙은 볼 홍조","original":"Blush Sticker","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"볼의 홍조를 납작한 타원이나 짧은 선으로 그려 귀여운 인상을 만든다. 실제 얼굴의 색 변화보다 그림체의 기호에 가깝다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003519/index.html"},{"id":"MEJE-KW-003520","row_version":1,"title":"저예산 장르 영화","original":"B-Movie","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"제작 자원이 적은 조건에서 익숙한 장르와 과감한 아이디어로 만들어진 영화 유형. 규모의 제약이 독특한 표현과 새로운 취향을 만들기도 한다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-003520/index.html"},{"id":"MEJE-KW-003522","row_version":3,"title":"상대 함선에 직접 올라타기","original":"Boarding Party","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"배나 우주선의 승무원이 적의 함선으로 건너가 사람이나 물건을 확보한다. 먼 거리의 싸움이 좁은 통로의 대면으로 바뀐다. 함선 사이의 거리를 넘는 장비로 함선 침투용 캡슐을 쓸 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003522/index.html"},{"id":"MEJE-KW-003523","row_version":2,"title":"함선 침투용 캡슐","original":"Boarding Pod","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"작은 탑승체를 상대 함선의 선체에 붙여 침투 인원을 들여보낸다. 외부에서 볼 때는 작은 충격이 내부에서는 큰 위협이 된다. 캡슐이 선체에 닿은 뒤 상대 함선에 직접 올라타기가 시작된다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003523/index.html"},{"id":"MEJE-KW-003524","row_version":2,"title":"기숙학교","original":"Boarding School","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"학생이 배우고 생활하는 공간을 함께 둔 학교. 수업 밖의 밤과 휴일에도 관계가 이어져 또래 집단의 작은 사회가 된다. 학교 안의 권력과 고립이 폭력으로 이어지면 위협적인 기숙학교가 된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-003524/index.html"},{"id":"MEJE-KW-003525","row_version":2,"title":"위협적인 기숙학교","original":"Boarding School of Horrors","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"닫힌 학교 안에서 권위와 또래의 폭력이 학생을 괴롭힌다. 외부와 떨어진 생활 구조가 도움을 구하기 어렵게 만든다. 같은 생활 공간이라도 기숙학교의 다른 가능성을 보여 준다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-003525/index.html"},{"id":"MEJE-KW-003526","row_version":1,"title":"계획을 들려준 뒤 청자를 없애기","original":"Board to Death","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"악역이 자기 계획을 여러 사람에게 설명한 다음 그들을 해친다. 관객에게 정보를 주면서도 이야기 속 비밀은 유지하는 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003526/index.html"},{"id":"MEJE-KW-003527","row_version":1,"title":"자랑이 화를 부르기","original":"Boast Backfire","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"우위를 과시하려던 말이 도전이나 반격의 계기가 되어 말한 사람을 곤란하게 한다. 무엇을 공개했는지가 실패의 이유가 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003527/index.html"},{"id":"MEJE-KW-003528","row_version":1,"title":"자신을 과시하는 랩","original":"Boastful Rap","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"랩 가사가 화자의 능력과 성취를 크게 자랑한다. 말의 과장과 리듬이 인물의 자신감을 무대 위 행동으로 만든다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003528/index.html"},{"id":"MEJE-KW-003529","row_version":1,"title":"퇴역한 배를 건물로 쓰기","original":"Boats into Buildings","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"항해를 멈춘 배를 주거지나 가게, 연구소 같은 고정된 공간으로 바꾼다. 배의 옛 구조가 새로운 생활의 동선을 만든다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-003529/index.html"},{"id":"MEJE-KW-003530","row_version":1,"title":"회계부서의 평범해 보이는 동료","original":"Bob from Accounting","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"이름과 부서만 알려진 직장 동료가 안정적인 일상의 상징처럼 등장한다. 그가 예상 밖의 개성을 보일 때 첫인상이 뒤집힌다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003530/index.html"},{"id":"MEJE-KW-003531","row_version":1,"title":"차분한 그림 강사의 말투를 패러디하기","original":"Bob Ross Rib","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"부드러운 목소리와 작은 칭찬으로 그림을 가르치는 형식을 다른 상황에 옮겨 웃음을 만든다. 평온한 말투와 화면 속 사건의 차이가 핵심이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003531/index.html"},{"id":"MEJE-KW-003532","row_version":1,"title":"반복되는 당김음의 록 리듬","original":"Bo Diddley Beat","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"짧은 리듬의 패턴을 되풀이해 곡의 추진력을 만든다. 악기와 편곡이 달라도 박자의 구조가 곡을 알아보게 한다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-003532/index.html"},{"id":"MEJE-KW-003533","row_version":1,"title":"특수 조명으로 드러나는 얼룩","original":"Bodily Fluid Blacklight Reveal","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"평소에는 잘 보이지 않던 몸에서 나온 액체의 흔적이 조명을 바꾼 뒤 나타난다. 발견한 사람의 반응과 그 흔적의 의미가 장면을 만든다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003533/index.html"},{"id":"MEJE-KW-003534","row_version":2,"title":"몸을 차지한 존재와 원래 주인","original":"Body and Host","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"한 몸 안에 들어온 존재와 그 몸의 원래 주인이 서로 다른 목적을 지닌다. 누가 움직이고 누가 결정하는지가 관계의 규칙이 된다. 원래 주인이 몸의 결정권을 잃으면 몸의 통제권을 빼앗는 존재의 상황이 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003534/index.html"},{"id":"MEJE-KW-003535","row_version":1,"title":"방어구를 추가 체력으로 계산하기","original":"Body Armor as Hit Points","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임의 방어구가 특정 공격을 막는 장비보다 먼저 닳는 체력 수치처럼 작동한다. 화면의 수치가 보호 상태를 간단히 전한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003535/index.html"},{"id":"MEJE-KW-003536","row_version":1,"title":"몸에 저장된 의식의 복사본","original":"Body Backup Drive","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"인물의 정신 정보를 몸속 장치에 보관해 다른 몸으로 옮길 가능성을 만든다. 저장된 기억과 이어지는 자아가 같은 사람인지 세계의 규칙이 묻게 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003536/index.html"},{"id":"MEJE-KW-003537","row_version":1,"title":"시신 운반 자루에 숨어 들어가기","original":"Bodybag Trick","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 시신을 나르는 물건 안에 숨어 경비 구역을 통과한다. 검문하는 사람이 무엇을 확인하지 않을지 계산한 침투 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003537/index.html"},{"id":"MEJE-KW-003538","row_version":1,"title":"몸으로 만드는 임시 다리","original":"Body Bridge","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"사람이나 생물이 틈 위에 몸을 걸쳐 다른 이들이 건너게 한다. 협력의 비용과 건너는 순서가 위기를 드러낸다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003538/index.html"},{"id":"MEJE-KW-003539","row_version":1,"title":"처치한 적의 수로 겨루기","original":"Body-Count Competition","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"전투 중 두 인물이 쓰러뜨린 상대의 수를 세며 경쟁한다. 목숨이 점수처럼 취급되는 태도가 인물의 가치관을 드러낸다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003539/index.html"},{"id":"MEJE-KW-003540","row_version":1,"title":"중요 인물을 대신하는 대역","original":"Body Double","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"위험한 자리에 닮은 사람을 세워 실제 인물의 위치와 목적을 감춘다. 외모의 유사성과 역할을 맡은 사람의 선택이 함께 중요하다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003540/index.html"},{"id":"MEJE-KW-003541","row_version":2,"title":"여성만으로 꾸린 호위대","original":"Bodyguard Babes","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"중요 인물의 호위 인력을 여성들로 구성한다. 이들을 장식처럼 쓰는지 각자의 판단과 전문성을 가진 인물로 그리는지 살핀다. 호위대 중 누군가가 임무를 저버리면 호위자의 배신의 갈등이 생긴다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003541/index.html"},{"id":"MEJE-KW-003542","row_version":2,"title":"호위자의 배신","original":"Bodyguard Betrayal","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"보호해야 할 사람의 비밀과 약점을 가장 잘 아는 호위자가 그를 해친다. 가까이 있을 권한이 배신의 통로가 된다. 대를 이은 책임까지 깨진다면 대를 이어 맡는 경호 임무의 의미도 흔들린다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003542/index.html"},{"id":"MEJE-KW-003543","row_version":1,"title":"호위 대상에게 마음이 생기기","original":"Bodyguard Crush","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"오랫동안 곁을 지키던 호위자와 보호받는 인물 사이에 호감이 싹튼다. 임무의 책임과 서로의 자발적인 선택을 구분한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003543/index.html"},{"id":"MEJE-KW-003544","row_version":1,"title":"스스로도 강한 인물을 경호하기","original":"Bodyguarding a Badass","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"위험에 맞설 능력이 있는 사람에게도 별도의 호위대가 붙는다. 힘이 있어도 지위와 책임 때문에 보호가 필요한 이유가 생긴다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003544/index.html"},{"id":"MEJE-KW-003545","row_version":2,"title":"대를 이어 맡는 경호 임무","original":"Bodyguard Legacy","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 집안이 여러 세대에 걸쳐 같은 인물이나 자리를 지킨다. 전해진 의무를 다음 사람이 스스로 받아들일지도 관계의 갈등이 된다. 세대를 잇던 신뢰가 무너지면 호위자의 배신의 무게가 더 커진다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003545/index.html"},{"id":"MEJE-KW-003546","row_version":2,"title":"몸의 변형이 두려움이 되는 공포","original":"Body Horror","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"몸의 형태와 감각이 낯설게 바뀌는 과정을 통해 공포를 만드는 표현. 변화 자체보다 인물이 자기 몸을 어떻게 느끼는지가 중심이다. 여러 몸이 합쳐진 여러 몸이 합쳐진 괴물은 몸의 경계가 무너지는 공포를 만들 수 있다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-003546/index.html"},{"id":"MEJE-KW-003547","row_version":1,"title":"뜻밖의 장소에서 발견한 시신","original":"Body in a Breadbox","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"시신이 평범한 발견 장소와 어울리지 않는 작은 공간에서 나온다. 발견 위치가 사건의 경위에 관한 새로운 질문을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003547/index.html"},{"id":"MEJE-KW-003548","row_version":1,"title":"신체 부위를 반복하는 상징","original":"Body Motifs","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"손이나 눈처럼 특정 신체 부위를 대사와 화면에 되풀이해 보여 준다. 반복되는 위치와 상황이 인물의 기억이나 주제를 묶는다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003548/index.html"},{"id":"MEJE-KW-003549","row_version":1,"title":"여러 몸이 합쳐진 괴물","original":"Body of Bodies","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"여러 존재의 몸이 하나로 이어져 새로운 생물이 된다. 남겨진 몸의 흔적이 그 존재의 탄생 과정에 대한 불안을 만든다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-003549/index.html"},{"id":"MEJE-KW-003550","row_version":1,"title":"매 회 등장하는 새로운 시신","original":"Body of the Week","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"수사나 검시를 다루는 이야기에서 새 회차마다 다른 사망자가 사건의 출발점이 된다. 사건을 푸는 사람과 죽은 이의 삶을 함께 보여 줄 수 있다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-003550/index.html"},{"id":"MEJE-KW-003551","row_version":1,"title":"몸에 직접 그리는 그림","original":"Body Paint","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"옷이나 종이 대신 피부에 색과 무늬를 그려 인물의 모습이나 집단의 표식을 만든다. 지워지는 시점도 연출의 일부다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003551/index.html"},{"id":"MEJE-KW-003552","row_version":1,"title":"옷이 없어도 나오는 몸속 주머니","original":"Body Pocket","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"옷을 입지 않은 만화 동물이 털이나 몸의 옆쪽에서 물건을 꺼낸다. 몸에 실제 주머니가 있는지는 장면의 편의에 따라 달라진다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003552/index.html"},{"id":"MEJE-KW-003553","row_version":2,"title":"다른 사람의 몸을 썰매로 타기","original":"Body Sled","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"한 인물이 몸을 뻗은 다른 사람 위에 올라타 미끄러져 이동한다. 이동 수단과 인물 사이의 힘 관계가 우스움이나 모욕을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003553/index.html"},{"id":"MEJE-KW-003554","row_version":2,"title":"몸의 통제권을 빼앗는 존재","original":"Body Snatcher","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"외부의 정신이 인물의 몸을 조종하고 원래 주인은 움직일 수 없게 된다. 주변 사람들이 같은 얼굴 속 다른 의도를 알아차리는지가 긴장을 만든다. 한 몸에 머물지 않는다면 몸을 바꿔 가며 이동하는 침입자로 위협이 이어진다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003554/index.html"},{"id":"MEJE-KW-003555","row_version":2,"title":"몸을 바꿔 가며 이동하는 침입자","original":"Body Surf","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"한 존재가 여러 사람의 몸을 차례로 차지하며 이동한다. 남겨진 몸과 기억이 추적의 단서가 된다. 몸을 옮겨 가는 동안 각 피해자에게 몸의 통제권을 빼앗는 존재이 일어난다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003555/index.html"},{"id":"MEJE-KW-003556","row_version":1,"title":"사람의 몸을 음식 접시처럼 쓰기","original":"Body Sushi","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"사람이 누운 몸 위에 음식을 배열해 보여 주는 장면. 음식의 진열과 몸을 바라보는 시선, 당사자의 동의를 함께 살핀다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003556/index.html"},{"id":"MEJE-KW-003557","row_version":1,"title":"몸에서 떨어져 나온 것이 보석이 되기","original":"Body to Jewel","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"눈물이나 피 같은 몸의 일부가 분리된 뒤 보석 같은 값진 물질로 바뀐다. 물건의 가치가 그 존재를 노리는 이유가 된다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003557/index.html"},{"id":"MEJE-KW-003558","row_version":1,"title":"몸째 가상 공간으로 들어가기","original":"Body Uploading","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"인물이 화면을 보기만 하는 대신 몸과 감각을 가상 공간 안에서 경험한다. 현실의 몸이 어디에 남는지가 위험과 귀환의 규칙이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003558/index.html"},{"id":"MEJE-KW-003559","row_version":2,"title":"인물의 몸으로 화면을 가리고 장면 바꾸기","original":"Body Wipe","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"인물이 카메라 앞을 지나 화면을 채우는 순간 다음 공간으로 편집한다. 몸의 움직임이 두 장면을 잇는 가림막이 된다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-003559/index.html"},{"id":"MEJE-KW-003560","row_version":2,"title":"글자 게임에 속마음이 나타나기","original":"Boggles the Mind","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"글자 타일로 만든 낱말이 플레이어의 걱정이나 욕망을 우연처럼 드러낸다. 게임의 점수보다 고른 말이 인물의 이야기를 한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003560/index.html"},{"id":"MEJE-KW-003561","row_version":1,"title":"유명한 복합 록 노래 패러디하기","original":"Bohemian Parody","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"여러 부분으로 극적으로 바뀌는 유명한 노래의 구조를 새 가사와 상황으로 바꿔 쓴다. 관객의 기억이 패러디를 알아보게 하는 장치다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003561/index.html"},{"id":"MEJE-KW-003562","row_version":2,"title":"시끄럽고 호탕한 싸움꾼","original":"Boisterous Bruiser","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"싸움을 두려워하지 않고 목소리와 행동이 큰 인물. 거친 태도 뒤에 동료를 돌보는 방식이 드러날 수 있다. 큰 목소리는 닮았지만 실제 힘이 부족한 허세가 큰 약한 싸움꾼과 구분된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003562/index.html"},{"id":"MEJE-KW-003563","row_version":2,"title":"허세가 큰 약한 싸움꾼","original":"Boisterous Weakling","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"상대를 도발하며 강한 척하지만 실제 대결에서는 힘이 부족한 인물. 두려움을 감추려는 태도인지 남을 괴롭히는 선택인지 구분한다. 허세가 실력을 갖춘 시끄럽고 호탕한 싸움꾼과 대비된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003563/index.html"},{"id":"MEJE-KW-003564","row_version":1,"title":"엉뚱한 말과 즉각적인 받아치기","original":"Boke and Tsukkomi Routine","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"한 사람이 일부러 잘못 짚거나 과장해 말하면 다른 사람이 곧바로 바로잡으며 웃음을 만든다. 두 역할의 박자가 대화의 리듬을 이룬다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003564/index.html"},{"id":"MEJE-KW-003565","row_version":2,"title":"남성형 1인칭을 쓰는 여성 캐릭터","original":"Bokukko","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"일본어 대사에서 여성 인물이 남성에게 흔히 쓰이는 1인칭을 선택한다. 말투의 특징을 성격이나 성별 정체성의 단정으로 연결하지 않는다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003565/index.html"},{"id":"MEJE-KW-003566","row_version":1,"title":"미지의 장소를 향하는 탐험가","original":"Bold Explorer","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"익숙한 곳을 떠나 처음 보는 장소와 사람을 찾아가는 인물. 발견의 기쁨과 이미 그곳에 살아온 사람들의 관점을 함께 둔다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003566/index.html"},{"id":"MEJE-KW-003567","row_version":1,"title":"일상 대사의 낱말마다 굵게 강조하기","original":"Bold Inflation","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"만화의 평범한 대사에 굵은 글씨를 자주 넣어 말의 강세를 표시한다. 강조가 많아지면 인물의 목소리보다 편집의 습관이 눈에 띈다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003567/index.html"},{"id":"MEJE-KW-003568","row_version":2,"title":"외계인과의 첫 만남을 성적 접근으로 시작하기","original":"Boldly Coming","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"낯선 종족을 만난 인물이 이해와 협상보다 성적 친밀감을 먼저 시도한다. 상대의 의사와 서로 다른 몸의 규칙이 관계의 중요한 조건이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003568/index.html"},{"id":"MEJE-KW-003569","row_version":2,"title":"죽음의 위기에서 끊기는 시즌","original":"Bolivian Army Cliffhanger","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"여러 인물이 살아남기 어려워 보이는 순간에 한 시즌을 끝낸다. 다음 시즌까지 생사를 미루는 구성이 기대와 불안을 만든다. 같은 위기를 이야기 전체의 끝에 두면 죽음을 앞둔 채 끝나는 이야기가 된다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-003569/index.html"},{"id":"MEJE-KW-003570","row_version":2,"title":"죽음을 앞둔 채 끝나는 이야기","original":"Bolivian Army Ending","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"주요 인물이 압도적인 위험 앞에 선 순간 결말을 멈춘다. 실제 결과를 보여 주지 않아 남겨진 가능성을 관객이 해석한다. 한 시즌의 끝에 쓰면 죽음의 위기에서 끊기는 시즌가 되고 다음 회차에 결과를 밝힐 수 있다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-003570/index.html"},{"id":"MEJE-KW-003571","row_version":2,"title":"인도인을 공부 잘하는 괴짜로만 그리기","original":"Bollywood Nerd","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인도 출신 인물에게 지적 능력과 괴짜 성향만 반복해 부여한다. 개인의 삶보다 국적에 붙은 기대가 캐릭터를 대신하는지 살핀다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003571/index.html"},{"id":"MEJE-KW-003572","row_version":1,"title":"신의 분노가 벼락으로 떨어지기","original":"Bolt of Divine Retribution","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"초월적 존재의 불만이 갑작스러운 벼락으로 나타난다. 벌을 내리는 기준과 그 힘을 받아들이는 사회가 세계의 규칙이 된다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003572/index.html"},{"id":"MEJE-KW-003573","row_version":1,"title":"같은 박자를 쌓아 커지는 음악","original":"Boléro Effect","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"반복되는 리듬 위에 악기와 소리를 더해 점점 큰 울림을 만든다. 변화가 적은 박자와 늘어나는 규모가 긴장을 쌓는다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-003573/index.html"},{"id":"MEJE-KW-003574","row_version":2,"title":"공중에서 물체를 떨어뜨리는 적","original":"Bombardier Mook","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"날아다니는 적이 플레이어의 머리 위에 물체를 떨구며 이동을 방해한다. 위쪽 공간을 살펴야 하는 게임 규칙이 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003574/index.html"},{"id":"MEJE-KW-003575","row_version":2,"title":"폭발물을 처리해야 하는 장면","original":"Bomb Disposal","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물들이 위험한 물체를 발견해 주변 사람을 보호할 방법을 찾는다. 실제 처리법보다 시간 압박과 판단의 책임을 다루는 허구 장면이다. 처리하지 못한 위험 앞에서 생활용품이 폭발을 막아 주는 장면 같은 생존 연출이 등장할 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003575/index.html"},{"id":"MEJE-KW-003576","row_version":1,"title":"지도 화면으로 전투 상황 보여 주기","original":"Bombers on the Screen","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"전장의 인물 대신 지도 위의 표시와 이동으로 전투를 보여 준다. 관객이 먼 거리의 판단과 전체 흐름을 한눈에 읽게 한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003576/index.html"},{"id":"MEJE-KW-003577","row_version":1,"title":"생활용품이 폭발을 막아 주는 장면","original":"Bombproof Appliance","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 집 안의 가전이나 욕조 뒤에 숨고 큰 폭발을 견딘다. 생활용품에 과장된 보호 능력을 준 허구의 생존 연출이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003577/index.html"},{"id":"MEJE-KW-003578","row_version":1,"title":"폭탄을 던지는 무정부주의자라는 고정관념","original":"Bomb-Throwing Anarchists","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"작품이 무정부주의를 주장하는 인물을 폭발만 바라는 사람으로 단순화한다. 정치적 입장과 개별 인물의 폭력적 행동을 같은 뜻으로 취급하는지 살핀다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003578/index.html"},{"id":"MEJE-KW-003579","row_version":1,"title":"떨어지는 폭탄의 휘파람 소리","original":"Bomb Whistle","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"공중에서 내려오는 물체에 길게 이어지는 높은 소리를 더한다. 아직 보이지 않는 위험의 방향과 시간을 청각으로 알린다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-003579/index.html"},{"id":"MEJE-KW-003580","row_version":1,"title":"성적 취향을 악의 증거로 삼기","original":"Bondage Is Bad","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물의 합의된 성적 취향을 악역이라는 표시처럼 사용한다. 타인의 경계를 해치는 행동과 취향 자체를 구분해 볼 필요가 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003580/index.html"},{"id":"MEJE-KW-003581","row_version":1,"title":"동료 집단을 갈라놓는 사건","original":"Bond Breaker","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"서로 믿던 동료들이 한 사건 뒤 편을 나눠 함께 움직이지 못한다. 갈등을 일으킨 행동과 관계를 다시 잇기 위한 조건이 이야기의 중심이 된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003581/index.html"},{"id":"MEJE-KW-003582","row_version":2,"title":"사람과 특별한 생물의 결속","original":"Bond Creatures","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"생물이 한 사람을 파트너로 택하고 서로의 힘이나 감각을 나눈다. 명령 관계인지 상호 선택인지에 따라 협력의 모습이 달라진다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003582/index.html"},{"id":"MEJE-KW-003583","row_version":1,"title":"총열 안쪽에서 보는 인물의 등장","original":"Bond Gun Barrel","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"화면을 총열 안쪽처럼 둥글게 가리고 인물이 돌아서며 관객을 향해 움직인다. 익숙한 첩보물의 장면을 인용하거나 변형하는 구도다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-003583/index.html"},{"id":"MEJE-KW-003584","row_version":2,"title":"술집에서 대화하며 가까워지기","original":"Bonding at the Bar","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"두 인물이 술집에서 함께 시간을 보내며 평소 못 하던 말을 나눈다. 술 자체보다 상대의 말을 듣고 응답하는 과정이 친밀함을 만든다. 술자리에서 나누는 공통의 불만이 함께 싫어하는 것에서 친해지기의 계기가 되기도 한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003584/index.html"},{"id":"MEJE-KW-003585","row_version":1,"title":"함께 싫어하는 것에서 친해지기","original":"Bonding Over Dislikes","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"두 사람이 좋아하는 것보다 싫어하는 대상이 같다는 사실로 가까워진다. 불만을 나누는 관계가 새 공통 목표로 이어질 수도 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003585/index.html"}]}.cards;